// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address caller, uint8 choice) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool initOk;
        try c.initialize() { initOk = true; } catch { initOk = false; }
        // only deployer is owner (already initialized); make caller the owner unless it already is
        if (!initOk && caller != address(this)) {
            // caller cannot become owner; skip non-owner domain is too narrow, so instead
            // transfer ownership from current owner to caller first when possible
        }
        // Determine ownership state: current owner is address(this) (deployer).
        // Rule: a call to transferOwnership with newOwner == address(0) MUST revert.
        // To let the fuzzer pick any actor, first move ownership to `caller` via current owner.
        vm.prank(address(this));
        bool handoverOk;
        try c.transferOwnership(caller) { handoverOk = true; } catch { handoverOk = false; }
        // Now the zero-address transfer decision is fuzz-driven (choice parity selects target)
        address target = (choice % 2 == 0) ? address(0) : caller;
        vm.prank(caller);
        bool ok;
        try c.transferOwnership(target) { ok = true; } catch { ok = false; }
        if (target == address(0)) {
            // GENERAL RULE: transferring ownership to the zero address always reverts
            assertTrue(!ok && c.owner() != address(0));
        } else {
            // GENERAL RULE: transferring to a non-zero address succeeds and updates owner()
            assertTrue(ok && (c.owner() == caller || !handoverOk));
        }
    }
}
